sections:
[
  {
    "key": "corpus_orientation",
    "heading": "Seven texts, two source windows, four citation modes",
    "claim": "The seven citing texts assign Lachmann roles that fall into four analytically distinct modes — grouped corroboration, selective evidence, authority citation, and theoretical reconstruction — and only two Lachmann source windows are held, limiting fidelity assessment to three of eleven citation pairs.",
    "reader_needs_next": "A passage-by-passage record of what each citation does and whether it can be verified",
    "evidence_kind": "vocabulary",
    "finding_ids": ["F1", "F2", "F5", "F8", "F11", "F14", "F17", "F24", "F27"],
    "table": {
      "intent": "Orient the researcher to the full corpus: one row per citing text, showing the Lachmann work cited, the citation mode, and whether a held source window permits fidelity comparison",
      "row_unit": "one citing text",
      "columns": ["Text and year", "Lachmann work(s) cited", "Citation mode", "Source window held?"],
      "carries_claims": [
        "The four citation modes are empirically distinct across the corpus",
        "Only two Lachmann source windows are held, leaving eight pairs unverifiable",
        "The two 2024 chapters assign Lachmann different modes in the same publication year"
      ]
    },
    "figure": null,
    "anchors_planned": [
      {
        "doc_key": "FWRCK8PM",
        "quote": "(Billings and Scott 1991; Burawoy 1990; Gramsci 1971; Lachmann 1988; Wright 2000)."
      },
      {
        "doc_key": "QASWYLCG",
        "quote": "Lachmann was the ﬁrst scholar to develop elite theory as a truly historical and explanatory framework by combining it with elements of Marxism."
      },
      {
        "doc_key": "EZWD7IBR",
        "quote": "Nonstate elites (elites are embedded within a distinct organisational apparatus and have the capacity to appropriate resources from non-elites; Lachmann, 2000, p. 9)"
      }
    ],
    "feeds": ["passage_record", "trajectory"]
  },
  {
    "key": "passage_record",
    "heading": "What each citation does: move, stance, and locus across all eleven passages",
    "claim": "Across eleven citation passages, Lachmann performs five argumentative moves — grouped corroboration, historical evidence, conceptual authority, authority citation, and theoretical dialogue — and the stance ranges from mere mention to sustained adoption and explicit qualification.",
    "reader_needs_next": "How these passage-level moves accumulate into a trajectory over time",
    "evidence_kind": "case_comparison",
    "finding_ids": ["F1", "F3", "F4", "F6", "F7", "F9", "F10", "F12", "F13", "F15", "F16", "F17", "F18", "F19", "F20", "F21", "F22", "F23", "F25", "F26"],
    "table": {
      "intent": "Prove that each citation performs a distinct and identifiable argumentative move; rows carry the move, stance, and the verbatim anchor that establishes it",
      "row_unit": "one citation passage (text + locus)",
      "columns": ["Text / locus", "Cited object and page", "Move", "Stance", "Anchor (verbatim)"],
      "carries_claims": [
        "Each passage performs a distinct, nameable argumentative move",
        "Stance ranges from mention to adoption to explicit qualification",
        "The recurrent elite definition at Capitalists p. 9 is adopted locally in three separate passages with different argumentative purposes",
        "The 2018 and 2021 citations perform moves (authority, illustration) that do not continue the elite-definition strand"
      ]
    },
    "figure": null,
    "anchors_planned": [
      {
        "doc_key": "EBSFFE5N",
        "quote": "the main mechanism of integrating both the nobility and the increasingly important merchant elite into French absolutism was the sale of offices"
      },
      {
        "doc_key": "UWEWLCPF",
        "quote": "elites, by definition, are embedded within a distinct organizational apparatus and have the capacity to appropriate resources from nonelites; Lachmann 2000:9"
      },
      {
        "doc_key": "3YLGA6BQ",
        "quote": "As Richard Lachmann's First Class Passengers on a Sinking Ship, forthcoming from Verso, clearly shows."
      },
      {
        "doc_key": "89QVNXT8",
        "quote": "(Bourdieu 1988 [1984]: xvii; Lachmann 2013: 65–67)."
      }
    ],
    "feeds": ["trajectory", "fidelity_audit"]
  },
  {
    "key": "trajectory",
    "heading": "From grouped parenthetical to central interlocutor: the 2002–2024 arc",
    "claim": "Lachmann's argumentative role increases from a thin parenthetical in 2002 to a reconstructed and explicitly qualified research programme in 2024, but the arc is not linear — the 2018 and 2021 citations follow independent routes, and the two 2024 chapters assign him different roles that cannot be chronologically ordered.",
    "reader_needs_next": "Whether the attributions that carry this trajectory can be verified against Lachmann's own words",
    "evidence_kind": "chronology",
    "finding_ids": ["F27", "F28", "F29", "F30", "F17", "F18", "F21", "F23"],
    "table": null,
    "figure": null,
    "anchors_planned": [
      {
        "doc_key": "FWRCK8PM",
        "quote": "(Billings and Scott 1991; Burawoy 1990; Gramsci 1971; Lachmann 1988; Wright 2000)."
      },
      {
        "doc_key": "QASWYLCG",
        "quote": "This formed a research programme that made it possible to explain how elites could change – or not change – social reality."
      },
      {
        "doc_key": "QASWYLCG",
        "quote": "some of the characteristic problems remained, and, in particular, forms of power were never clearly speciﬁed."
      },
      {
        "doc_key": "EBSFFE5N",
        "quote": "Richard Lachmann, Capitalists in Spite of Themselves: Elite Conflict and Economic Transitions in Early Modern Europe (New York: Oxford University Press, 2000), 133–36."
      }
    ],
    "feeds": ["fidelity_audit", "conclusion"]
  },
  {
    "key": "fidelity_audit",
    "heading": "Citation fidelity: one accurate, two fair, eight unverified",
    "claim": "Of the eleven citation pairs, only three can be compared with held source text: the fiscal-military attribution to States and Power is accurate, the two casualty-tolerance and hegemonic-decline attributions to First-Class Passengers are fair but involve categorical extension or partial reconstruction, and the remaining eight — including the recurrent elite definition and the office-selling account — are unverifiable because the cited pages are not held.",
    "reader_needs_next": "Which unverified attributions matter most and what a researcher must obtain to settle them",
    "evidence_kind": "cost_ledger",
    "finding_ids": ["F8", "F9", "F10", "F11", "F12", "F13", "F14", "F15", "F16", "F17", "F18", "F19"],
    "table": {
      "intent": "Prove the fidelity verdict for each of the eleven pairs; rows carry the attribution kind, the A-side anchor, the P-side anchor (where held), and the verdict with its reason",
      "row_unit": "one citation pair",
      "columns": ["Pair / text", "Attribution kind", "A-side anchor (verbatim)", "P-side evidence", "Verdict and reason"],
      "carries_claims": [
        "The fiscal-military attribution is accurate: the held pages support the cited proposition",
        "The casualty-tolerance attribution is fair: Riley extends a US-centred historical account to a categorical claim about the developed world",
        "The hegemonic-decline attribution is fair: the held passage supports the causal direction but not the full reconstruction",
        "Eight pairs, including the recurrent elite definition at Capitalists p. 9, are unverifiable because the cited pages are not held",
        "Unverifiability is a retrieval limit, not evidence of error"
      ]
    },
    "figure": null,
    "anchors_planned": [
      {
        "doc_key": "UWEWLCPF",
        "quote": "War and its associated goals of territorial defense or expansion were expensive, and taxation was necessary to finance them"
      },
      {
        "doc_key": "UWEWLCPF",
        "quote": "(Braddick 1994:5; Braun 1975:268–269, 310–313; Brewer 1989:xx–xxi; Carruthers 1996:8–9; Higgs 2004:44–46; Lachmann 2010:68–69;"
      },
      {
        "doc_key": "3YLGA6BQ",
        "quote": "They are not willing to die for their country."
      },
      {
        "doc_key": "UWEWLCPF",
        "quote": "From the state-driven perspective, strong states should have produced more extensive information than weak ones. Yet, we show the reverse."
      }
    ],
    "feeds": ["conclusion"]
  },
  {
    "key": "conclusion",
    "heading": "Two unsettled questions and one retrieval priority",
    "claim": "The evidence establishes the trajectory and the fidelity of the verified pairs, but cannot settle whether relational power theory extends or supersedes Lachmann's programme, nor whether the recurrent elite definition and office-selling account are faithfully rendered — and both questions turn on obtaining Capitalists in Spite of Themselves, pages 9 and 133–36.",
    "reader_needs_next": "Nothing — this is the action section",
    "evidence_kind": "implication",
    "finding_ids": ["F23", "F28", "F30", "F17", "F19"],
    "table": null,
    "figure": null,
    "anchors_planned": [
      {
        "doc_key": "QASWYLCG",
        "quote": "Lachmann (2000) deﬁned elites "as a group of rulers with the capacity to appropriate resources from nonelites and who inhabit a distinct organizational apparatus""
      },
      {
        "doc_key": "QASWYLCG",
        "quote": "Lachmann was mostly looking at economic resources."
      },
      {
        "doc_key": "QASWYLCG",
        "quote": "because Lachmann did not have a fully developed theory of power, he was never fully able to analyze adequately either"
      },
      {
        "doc_key": "EBSFFE5N",
        "quote": "The pre-revolutionary French state, in sum, was not at all a modern state, nor arguably was it on the way to becoming a modern state."
      }
    ],
    "feeds": []
  }
]
